<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
$user=current_user();$method=$_SERVER['REQUEST_METHOD'];
if($method==='POST'){require_csrf();db()->prepare('UPDATE users SET notifications_read_at=UTC_TIMESTAMP() WHERE tenant_id=? AND id=?')->execute([$user['tenant_id'],$user['id']]);respond(['message'=>'Notifications marked as read.']);}
if($method!=='GET')throw new ApiError(405,'Method not allowed.');
$read=db()->prepare('SELECT notifications_read_at FROM users WHERE tenant_id=? AND id=?');$read->execute([$user['tenant_id'],$user['id']]);$readAt=$read->fetchColumn()?:null;$events=[];
$campaignWhere=$user['role']==='MEMBER'?' AND created_by=?':'';$params=[$user['tenant_id']];if($campaignWhere)$params[]=$user['id'];
$q=db()->prepare("SELECT public_id,status,name,updated_at FROM campaigns WHERE tenant_id=? AND status IN ('COMPLETED','FAILED','PAUSED') AND updated_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY{$campaignWhere} ORDER BY updated_at DESC LIMIT 30");$q->execute($params);foreach($q->fetchAll() as $row){$label=match($row['status']){'COMPLETED'=>'completed','FAILED'=>'failed',default=>'was paused'};$events[]=['id'=>'campaign-'.$row['public_id'].'-'.$row['status'].'-'.$row['updated_at'],'title'=>$row['name'].' '.$label.'.','createdAt'=>$row['updated_at'],'link'=>'/campaigns/'.$row['public_id'],'kind'=>strtolower($row['status'])];}
$replyWhere=$user['role']==='MEMBER'?' AND c.created_by=?':'';$params=[$user['tenant_id']];if($replyWhere)$params[]=$user['id'];$q=db()->prepare("SELECT r.public_id,r.sender_email,r.received_at,c.public_id campaign_id FROM email_replies r JOIN campaigns c ON c.id=r.campaign_id AND c.tenant_id=r.tenant_id WHERE r.tenant_id=? AND r.reply_type='HUMAN' AND r.received_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY{$replyWhere} ORDER BY r.received_at DESC LIMIT 30");$q->execute($params);foreach($q->fetchAll() as $row)$events[]=['id'=>'reply-'.$row['public_id'],'title'=>'New reply from '.$row['sender_email'].'.','createdAt'=>$row['received_at'],'link'=>'/campaigns/'.$row['campaign_id'],'kind'=>'reply'];
$importWhere=$user['role']==='MEMBER'?' AND created_by=?':'';$params=[$user['tenant_id']];if($importWhere)$params[]=$user['id'];$q=db()->prepare("SELECT public_id,original_filename,status,imported_rows,failed_rows,updated_at FROM import_jobs WHERE tenant_id=? AND status IN ('COMPLETED','FAILED') AND updated_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY{$importWhere} ORDER BY updated_at DESC LIMIT 20");$q->execute($params);foreach($q->fetchAll() as $row){$title=$row['status']==='COMPLETED'?$row['imported_rows'].' leads imported from '.$row['original_filename'].'.':'Import failed: '.$row['original_filename'].'.';$events[]=['id'=>'import-'.$row['public_id'].'-'.$row['status'],'title'=>$title,'createdAt'=>$row['updated_at'],'link'=>'/import','kind'=>strtolower($row['status'])];}
if($user['role']!=='MEMBER'){$q=db()->prepare("SELECT public_id,sender_email,status,imap_last_error,updated_at FROM smtp_accounts WHERE tenant_id=? AND (status='ERROR' OR imap_last_error IS NOT NULL) AND updated_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY ORDER BY updated_at DESC LIMIT 20");$q->execute([$user['tenant_id']]);foreach($q->fetchAll() as $row)$events[]=['id'=>'smtp-'.$row['public_id'].'-'.$row['updated_at'],'title'=>$row['sender_email'].' needs attention.','createdAt'=>$row['updated_at'],'link'=>'/accounts','kind'=>'error'];}
usort($events,static fn($a,$b)=>strcmp($b['createdAt'],$a['createdAt']));$events=array_slice($events,0,30);$unread=0;foreach($events as &$event){$event['unread']=$readAt===null||$event['createdAt']>$readAt;if($event['unread'])$unread++;$event['createdAt']=gmdate('c',strtotime($event['createdAt'].' UTC'));}respond(['items'=>$events,'unreadCount'=>$unread]);
